```bash
# Убедимся, что директория для сайта существует
mkdir -p /srv/www

# Создадим файл с HTML-контентом
echo "<html><body><h1>Hello, World!</h1></body></html>" > /srv/www/index.html

# Убедимся, что конфигурационный файл nginx существует и не содержит ошибок
cat <<EOF > /etc/nginx/sites-enabled/app
server {
    listen 8080;
    root /srv/www;
    index index.html;
    location / {
        try_files \$uri \$uri/ =404;
    }
}
EOF

# Проверим конфигурацию nginx
nginx -t

# Перезапустим nginx для применения изменений
nginx -s reload
```

